using System;
using System.IO;
using System.Drawing;
using System.Windows.Forms;
namespace FleetLab
{
    internal static class PracticeProducedLaunchFormChecks
    {
        static void Need(bool ok,string text){if(!ok)throw new Exception(text);}
        static T Find<T>(Form f,string name)where T:Control{return(T)f.Controls.Find(name,true)[0];}
        static void Show(Form f,Form owner){f.ShowInTaskbar=false;f.StartPosition=FormStartPosition.Manual;f.Location=new Point(-20000,-20000);f.Show(owner);Application.DoEvents();}
        internal static void Run(Action<string,Action> check,string assets,Form owner)
        {
            string programs=Path.Combine(Path.GetDirectoryName(assets),"Programs");var map=PracticeMapStartup.CreateBssb202(programs,File.ReadAllBytes(Path.Combine(assets,"Graphics","BSSB202.SCN")),731);var joined=PracticeVisibleCandidates.Create(programs,map,PracticeOwnerVisibilityStudyState.Create(programs,map,0,1,0,1,0,0,0).Execute());Func<int,PracticeFleetMemberPreparation> prefix=delegate(int task){return PracticeFleetMemberPreparation.CreateFromVisibility(programs,map,joined,task,2,false,0).Advance().Advance().Advance();};Func<int,PracticeFleetMemberRequests> requests=delegate(int task){return PracticeFleetMemberRequests.CreateFromPreparation(prefix(task),0,0).Execute();};
            check("Natural-distance consumer form distinguishes held timers F2 rejection and pending reset",delegate
            {
                using(var f=new PracticeProducedLaunchStudy(programs,requests(0))){Show(f,owner);Find<Button>(f,"producedLaunchExecute").PerformClick();Need(f.StudyState.Timer(0)==29845&&f.StudyState.RequestCount(0)==10&&f.StudyState.CreatedObjects==0,"Held diagnostic timer");Find<ComboBox>(f,"producedLaunchTimer").SelectedIndex=1;Find<Button>(f,"producedLaunchReset").PerformClick();Need(f.StudyState.TimerMode==0&&!f.StudyState.Executed&&Find<ComboBox>(f,"producedLaunchTimer").SelectedIndex==1,"Pending timer/reset");Find<Button>(f,"producedLaunchLoad").PerformClick();Find<Button>(f,"producedLaunchExecute").PerformClick();Need(f.StudyState.RejectedRows==2&&f.StudyState.RequestCount(0)==0&&Find<Label>(f,"producedLaunchSummary").Text.Contains("OutOfRange")&&!Find<Button>(f,"producedLaunchExecute").Enabled,"F2 numeric denial presentation");f.Close();}
            });
            check("Natural-distance F3 consumer form shows allocated slots ammo and capacity at minimum size",delegate
            {
                using(var f=new PracticeProducedLaunchStudy(programs,requests(8))){Show(f,owner);Find<ComboBox>(f,"producedLaunchTimer").SelectedIndex=1;Find<Button>(f,"producedLaunchLoad").PerformClick();Find<Button>(f,"producedLaunchExecute").PerformClick();Need(f.StudyState.CreatedObjects==2&&Find<ListBox>(f,"producedLaunchObjects").Items.Count==2&&f.StudyState.Ammunition(0)==7,"F3 allocations");Find<ListBox>(f,"producedLaunchObjects").SelectedIndex=1;Need(Find<TextBox>(f,"producedLaunchDetails").Text.Contains("unit 31"),"Viewed F3 record");Find<ComboBox>(f,"producedLaunchCapacity").SelectedIndex=1;Find<Button>(f,"producedLaunchLoad").PerformClick();Find<Button>(f,"producedLaunchExecute").PerformClick();Need(f.StudyState.CreatedObjects==1&&f.StudyState.Projectiles[0].Slot==79&&f.StudyState.Ammunition(1)==8,"One-free capacity");Find<ComboBox>(f,"producedLaunchCapacity").SelectedIndex=2;Find<Button>(f,"producedLaunchLoad").PerformClick();Find<Button>(f,"producedLaunchExecute").PerformClick();Need(f.StudyState.CreatedObjects==0&&f.StudyState.ConsumedRequests==2&&f.StudyState.Ammunition(0)==8,"Full capacity");f.Size=f.MinimumSize;Application.DoEvents();Need(Find<Panel>(f,"producedLaunchScroll").AutoScroll&&Find<Control>(f,"producedLaunchCanvas").Width>500,"Minimum consumer layout");f.Close();}
            });
            check("Produced request consumer child requires completed global0 empty fixture and preserves parent",delegate
            {
                using(var parent=new PracticeFleetMemberRequestStudy(programs,map,prefix(0)))
                {
                    Show(parent,owner);var button=Find<Button>(parent,"memberRequestConsumer");Need(!button.Enabled,"Pending request consumer enabled");Find<Button>(parent,"memberRequestExecute").PerformClick();Need(button.Enabled,"Completed produced requests unavailable");var before=parent.StudyState;bool saw=false;Exception failure=null;int ticks=0;
                    using(var timer=new Timer{Interval=100}){timer.Tick+=delegate{if(++ticks>30){timer.Stop();failure=new Exception("Natural-distance consumer child missing");parent.Close();return;}foreach(Form child in parent.OwnedForms){var c=child as PracticeProducedLaunchStudy;if(c==null)continue;timer.Stop();try{Find<ComboBox>(c,"producedLaunchTimer").SelectedIndex=1;Find<Button>(c,"producedLaunchLoad").PerformClick();Find<Button>(c,"producedLaunchExecute").PerformClick();Need(c.StudyState.RejectedRows==2,"Child source admission");saw=true;}catch(Exception e){failure=e;}finally{c.Close();}return;}};timer.Start();button.PerformClick();timer.Stop();}
                    if(failure!=null)throw failure;Need(saw&&Object.ReferenceEquals(before,parent.StudyState)&&parent.StudyState.QueuedCells.Count==20,"Consumer changed request parent");Find<ComboBox>(parent,"memberRequestGlobalWeapon").SelectedIndex=1;Find<Button>(parent,"memberRequestLoad").PerformClick();Find<Button>(parent,"memberRequestExecute").PerformClick();Need(!button.Enabled,"Uncaptured global-field consumer enabled");parent.Close();
                }
            });
        }
        internal static int SavePreviews(string assets,string destination)
        {
            destination=Path.GetFullPath(destination);if(Directory.Exists(destination)||File.Exists(destination))throw new IOException("Choose a new natural-distance preview directory.");Directory.CreateDirectory(destination);string programs=Path.Combine(Path.GetDirectoryName(assets),"Programs");var map=PracticeMapStartup.CreateBssb202(programs,File.ReadAllBytes(Path.Combine(assets,"Graphics","BSSB202.SCN")),731);var joined=PracticeVisibleCandidates.Create(programs,map,PracticeOwnerVisibilityStudyState.Create(programs,map,0,1,0,1,0,0,0).Execute());Func<int,PracticeFleetMemberPreparation> prefix=delegate(int task){return PracticeFleetMemberPreparation.CreateFromVisibility(programs,map,joined,task,2,false,0).Advance().Advance().Advance();};Func<int,PracticeFleetMemberRequests> requests=delegate(int task){return PracticeFleetMemberRequests.CreateFromPreparation(prefix(task),0,0).Execute();};Action<Form,string> capture=delegate(Form f,string name){f.PerformLayout();Application.DoEvents();using(var b=new Bitmap(f.Width,f.Height)){f.DrawToBitmap(b,new Rectangle(Point.Empty,f.Size));b.Save(Path.Combine(destination,name+".png"),System.Drawing.Imaging.ImageFormat.Png);}};
            using(var parent=new PracticeFleetMemberRequestStudy(programs,map,prefix(0))){Show(parent,null);Find<Button>(parent,"memberRequestExecute").PerformClick();Find<Panel>(parent,"memberRequestScroll").ScrollControlIntoView(Find<Button>(parent,"memberRequestConsumer"));capture(parent,"01-Request-Entry");parent.Close();}
            using(var f=new PracticeProducedLaunchStudy(programs,requests(0))){Show(f,null);Find<Button>(f,"producedLaunchExecute").PerformClick();capture(f,"02-F2-Held");Find<ComboBox>(f,"producedLaunchTimer").SelectedIndex=1;Find<Button>(f,"producedLaunchLoad").PerformClick();Find<Button>(f,"producedLaunchExecute").PerformClick();capture(f,"03-F2-Range-Denial");f.Close();}
            using(var f=new PracticeProducedLaunchStudy(programs,requests(8))){Show(f,null);Find<Button>(f,"producedLaunchExecute").PerformClick();capture(f,"04-F3-Held");Find<ComboBox>(f,"producedLaunchTimer").SelectedIndex=1;Find<Button>(f,"producedLaunchLoad").PerformClick();Find<Button>(f,"producedLaunchExecute").PerformClick();Find<ListBox>(f,"producedLaunchObjects").SelectedIndex=1;capture(f,"05-F3-Two-Allocated");Find<ComboBox>(f,"producedLaunchCapacity").SelectedIndex=1;Find<Button>(f,"producedLaunchLoad").PerformClick();Find<Button>(f,"producedLaunchExecute").PerformClick();capture(f,"06-F3-Last-Free");Find<ComboBox>(f,"producedLaunchCapacity").SelectedIndex=2;Find<Button>(f,"producedLaunchLoad").PerformClick();Find<Button>(f,"producedLaunchExecute").PerformClick();capture(f,"07-F3-Full");f.Size=f.MinimumSize;capture(f,"08-Minimum-Controls");Find<Panel>(f,"producedLaunchScroll").ScrollControlIntoView(Find<TextBox>(f,"producedLaunchDetails"));capture(f,"09-Minimum-Details");f.Close();}
            File.WriteAllText(Path.Combine(destination,"Scope.txt"),"Nine actual-form natural-distance consumer previews. Actual map/equipment/observers/producedflags held;timer/capacity explicitfixtures. Numericadmission/allocation only,no motion/impact/damage/fullAI/world,media/audio or physicalacceptance.\r\n");return 0;
        }
    }
}
